const rotaryStyle=document.createElement('style');rotaryStyle.textContent=`.board{background:#344849;border:9px solid #a9b7aa;border-bottom-width:3px;box-shadow:inset 0 0 20px #0004;margin-bottom:0;border-radius:8px 8px 0 0}.leverbank{border:9px solid #a9b7aa;border-top:0;border-radius:0 0 8px 8px;background:#344849;box-shadow:0 12px 0 #17211b;padding-top:5px;margin-bottom:32px}.levergrid{grid-template-columns:repeat(8,minmax(0,1fr));gap:7px}.lever{height:96px;border:0;background:transparent;box-shadow:none;overflow:visible}.lever .slot{width:67px;height:67px;left:calc(50% - 33.5px);top:16px;border-radius:50%;background:radial-gradient(circle,#192122 0 48%,#839087 50% 55%,#1d2827 57% 67%,#acb5a2 69% 73%,#23312e 75%);box-shadow:0 4px 4px #0008}.lever .arm{height:53px;width:16px;top:24px;left:calc(50% - 8px);transform-origin:50% 26px;transform:rotate(0deg);background:linear-gradient(90deg,#7c2c25,#e17c68 45%,#793227);box-shadow:2px 2px 2px #0008;border:1px solid #521c16;border-radius:6px}.lever .grip{display:none}.lever.point .arm{background:linear-gradient(90deg,#101414,#5a6260,#131918);border-color:#131918}.lever.reverse .arm{transform:rotate(55deg)}.lever.outbound.reverse .arm{transform:rotate(-55deg)}.lever.locked:after{bottom:0;right:calc(50% - 15px);font-size:9px}.levernum{font-size:16px;margin:6px 0}.leverstate{font-size:11px}.levercaption{font-size:11px}.levermark{position:absolute;left:0;right:0;top:0;color:#ecedcb;font-size:10px}.lever:hover{background:#ffffff08}.rail{stroke:#7f9690}.rail.route{stroke:#f4f4cf}.rail.occupied{stroke:#ff6757}.board .label{fill:#e5e8ca}.levernote{color:#dae0cd} .leverhint{background:#253a36}.leverbank small{color:#d7dfc9}@media(max-width:900px){.levergrid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:500px){.levergrid{grid-template-columns:repeat(2,minmax(0,1fr))}}`;document.head.append(rotaryStyle);
let handles=Array(6).fill(false);const ids=['S1','S2','S3','D1','D2','D3'];
for(let i=0;i<8;i++){let mark=document.createElement('span');mark.className='levermark';mark.textContent=i<2?'N　│　R':i<5?'N　│　R →':'← L　│　N';$('lever'+i).append(mark);if(i>=5)$('lever'+i).classList.add('outbound');if(i<2)continue;let k=i-2,n=k%3+1,d=k<3?'in':'out';$('lever'+i).onclick=()=>{if(play.ended)return;if(handles[k]){handles[k]=false;if(s.r?.n===n&&s.r?.d===d)cancel();else tell(`${ids[k]}を中立Nに復位。`);return render()}if(handles.some(Boolean))return tell('先に使用済みの信号テコを中立Nへ復位してください。');if(s.r)return tell('競合鎖錠：先行進路の解錠を待ってください。');let w=req(n);if(s.w.some((v,j)=>v!==w[j]))return tell(`転てつ器照査不成立：W1＝${w[0]?'R':'N'}、W2＝${w[1]?'R':'N'}に合わせてください。`);$('dir').value=d;$('dest').value=String(n);setRoute();if(s.r?.n===n&&s.r?.d===d)handles[k]=true;render()}}
const preRotaryRender=render;render=()=>{preRotaryRender();for(let k=0;k<6;k++){let el=$('lever'+(k+2)),n=k%3+1,d=k<3?'in':'out';el.classList.toggle('reverse',handles[k]);el.setAttribute('aria-pressed',String(handles[k]));let green=!!(s.r?.n===n&&s.r?.d===d&&s.r.green);$('leverstate'+(k+2)).textContent=`${handles[k]?(k<3?'R':'L'):'N'} ／ ${green?'進行':'停止'}`;}if(handles.some(Boolean)&&!s.r){$('next').textContent='使用済みの信号テコを中立Nに戻す';$('tip').textContent='信号の停止と、テコの復位は別です。倒した赤いテコをもう一度クリック。';$('leverhint').textContent='信号テコ復位待ち。Nへ戻してから次の進路を扱ってください。'}};
const preRotaryReset=reset;reset=()=>{handles.fill(false);preRotaryReset()};const preRestart=restart;restart=mode=>{handles.fill(false);preRestart(mode)};
document.querySelector('.board small').textContent='灰：空き　白：進路　赤：在線';document.querySelector('.leverbank .row small').textContent='黒：転てつテコ　赤：信号テコ';document.querySelector('.levernote').textContent='継電連動盤風・個別操作モード。信号：中立N＝停止、入場R＝右回し、出発L＝左回し。転てつ：N＝定位、R＝反位。';
const research=document.createElement('p');research.innerHTML='外観参考：<a href="https://www.t-solinx.co.jp/product/01-tetsudo-shingo/01_002/" target="_blank" rel="noopener">T-SoLinx 製品写真</a> ／ <a href="https://musikfest.ran-maru.net/OJR014.html" target="_blank" rel="noopener">保存継電連動盤の写真</a>。配線図と短い回転テコの一体配置を参考にした架空盤です。N/R/Lの角度・色分けは本ゲームの設定で、全形式に共通する規格を表すものではありません。信号は列車進入で自動停止しますが、赤テコは手動で中立へ復位してください。';document.querySelector('details').append(research);render();
